[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellStream Platform — Integrated Energy Data Management</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --navy: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #243447;
  --dark-gray: #3C424B;
  --teal: #00B4D8;
  --teal-dark: #0077B6;
  --green: #6CC24A;
  --white: #F0F4F8;
  --white-dim: #A0AEC0;
  --surface: #162232;
  --font-display: 'Space Grotesk', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;
}
body { font-family: var(--font-body); background: var(--navy); color: var(--white); line-height: 1.6; overflow-x: hidden; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; }
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* Grain overlay */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E") repeat;
  pointer-events: none;
  z-index: 9999;
}

/* ===== NAV ===== */
.nav { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; background: rgba(13,27,42,0.92); backdrop-filter: blur(16px); border-bottom: 1px solid rgba(0,180,216,0.1); }
.nav-inner { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; max-width: 1200px; margin: 0 auto; }
.nav-logo { font-family: var(--font-display); font-weight: 700; font-size: 22px; color: var(--white); }
.nav-logo span { color: var(--teal); }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a { font-size: 14px; font-weight: 500; color: var(--white-dim); transition: color 0.2s; }
.nav-links a:hover { color: var(--teal); }
.nav-dropdown { position: relative; }
.nav-dropdown-btn { font-size: 14px; font-weight: 500; color: var(--white-dim); cursor: pointer; background: none; border: none; font-family: var(--font-body); display: flex; align-items: center; gap: 4px; transition: color 0.2s; }
.nav-dropdown-btn:hover { color: var(--teal); }
.nav-dropdown-menu { position: absolute; top: 100%; left: 0; margin-top: 12px; background: var(--navy-mid); border: 1px solid rgba(0,180,216,0.15); border-radius: 8px; padding: 8px; min-width: 200px; opacity: 0; visibility: hidden; transform: translateY(-8px); transition: all 0.2s; }
.nav-dropdown:hover .nav-dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.nav-dropdown-menu a { display: block; padding: 10px 16px; font-size: 14px; color: var(--white-dim); border-radius: 6px; transition: all 0.15s; }
.nav-dropdown-menu a:hover { background: rgba(0,180,216,0.1); color: var(--teal); }
.nav-cta { background: var(--teal); color: var(--navy); font-weight: 600; padding: 10px 24px; border-radius: 6px; font-size: 14px; transition: all 0.2s; border: none; cursor: pointer; font-family: var(--font-body); }
.nav-cta:hover { background: var(--teal-dark); color: var(--white); }

/* Mobile nav */
.nav-mobile-toggle { display: none; background: none; border: none; color: var(--white); cursor: pointer; padding: 4px; }
.nav-mobile-toggle svg { width: 24px; height: 24px; }

@media (max-width: 768px) {
  .nav-links { display: none; position: absolute; top: 100%; left: 0; right: 0; flex-direction: column; background: var(--navy-mid); padding: 16px; gap: 8px; border-bottom: 1px solid rgba(0,180,216,0.1); }
  .nav-links.active { display: flex; }
  .nav-links a, .nav-dropdown-btn { padding: 12px 16px; width: 100%; }
  .nav-dropdown-menu { position: static; opacity: 1; visibility: visible; transform: none; margin-top: 0; background: rgba(0,0,0,0.2); border: none; }
  .nav-dropdown:hover .nav-dropdown-menu { opacity: 1; }
  .nav-mobile-toggle { display: block; }
  .nav-cta { width: 100%; text-align: center; }
}

/* ===== HERO ===== */
.hero { padding: 160px 0 100px; position: relative; overflow: hidden; }
.hero::before { content: ''; position: absolute; top: -50%; right: -20%; width: 800px; height: 800px; background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%); pointer-events: none; }
.hero::after { content: ''; position: absolute; bottom: -30%; left: -10%; width: 600px; height: 600px; background: radial-gradient(circle, rgba(0,119,182,0.06) 0%, transparent 70%); pointer-events: none; }
.hero-badge { display: inline-flex; align-items: center; gap: 8px; background: rgba(0,180,216,0.1); border: 1px solid rgba(0,180,216,0.2); border-radius: 100px; padding: 6px 16px; font-size: 13px; font-weight: 500; color: var(--teal); margin-bottom: 24px; }
.hero-badge::before { content: ''; width: 6px; height: 6px; background: var(--teal); border-radius: 50%; animation: pulse 2s infinite; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
.hero h1 { font-family: var(--font-display); font-size: 56px; font-weight: 700; line-height: 1.1; max-width: 800px; margin-bottom: 24px; letter-spacing: -1px; }
.hero h1 .accent { color: var(--teal); }
.hero p { font-size: 18px; color: var(--white-dim); max-width: 600px; margin-bottom: 40px; line-height: 1.7; }
.hero-ctas { display: flex; gap: 16px; flex-wrap: wrap; }
.btn-primary { background: var(--teal); color: var(--navy); font-weight: 600; padding: 14px 32px; border-radius: 8px; font-size: 15px; transition: all 0.25s; display: inline-flex; align-items: center; gap: 8px; border: none; cursor: pointer; font-family: var(--font-body); }
.btn-primary:hover { background: #33c5e3; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,180,216,0.3); }
.btn-secondary { background: transparent; color: var(--white); font-weight: 600; padding: 14px 32px; border-radius: 8px; font-size: 15px; border: 1px solid rgba(255,255,255,0.2); transition: all 0.25s; display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-family: var(--font-body); }
.btn-secondary:hover { border-color: var(--teal); color: var(--teal); }

/* ===== FEATURED BANNER ===== */
.featured-banner { background: linear-gradient(135deg, var(--navy-mid) 0%, rgba(0,180,216,0.08) 100%); border: 1px solid rgba(0,180,216,0.15); border-radius: 16px; padding: 48px; display: flex; align-items: center; justify-content: space-between; margin-bottom: 100px; gap: 32px; }
.featured-banner-content h3 { font-family: var(--font-display); font-size: 14px; text-transform: uppercase; letter-spacing: 2px; color: var(--teal); margin-bottom: 8px; }
.featured-banner-content h2 { font-family: var(--font-display); font-size: 32px; font-weight: 700; margin-bottom: 4px; }
.featured-banner-content p { color: var(--white-dim); font-size: 15px; }
.featured-banner .btn-primary { white-space: nowrap; }
@media (max-width: 768px) {
  .featured-banner { flex-direction: column; padding: 32px 24px; text-align: center; }
}

/* ===== USE CASES ===== */
.section { padding: 80px 0; }
.section-label { font-size: 13px; text-transform: uppercase; letter-spacing: 3px; color: var(--teal); font-weight: 600; margin-bottom: 12px; }
.section-title { font-family: var(--font-display); font-size: 40px; font-weight: 700; margin-bottom: 16px; letter-spacing: -0.5px; }
.section-desc { font-size: 16px; color: var(--white-dim); max-width: 640px; margin-bottom: 48px; line-height: 1.7; }
.use-cases-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-bottom: 40px; }
.use-case-card { background: var(--surface); border: 1px solid rgba(255,255,255,0.06); border-radius: 12px; padding: 32px; transition: all 0.3s; cursor: pointer; position: relative; overflow: hidden; }
.use-case-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: linear-gradient(90deg, var(--teal), var(--teal-dark)); opacity: 0; transition: opacity 0.3s; }
.use-case-card:hover { border-color: rgba(0,180,216,0.3); transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.3); }
.use-case-card:hover::before { opacity: 1; }
.use-case-icon { width: 48px; height: 48px; background: rgba(0,180,216,0.1); border-radius: 10px; display: flex; align-items: center; justify-content: center; margin-bottom: 20px; color: var(--teal); }
.use-case-card h3 { font-family: var(--font-display); font-size: 18px; font-weight: 600; margin-bottom: 10px; }
.use-case-card p { font-size: 14px; color: var(--white-dim); line-height: 1.6; }
@media (max-width: 1024px) { .use-cases-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 640px) { .use-cases-grid { grid-template-columns: 1fr; } }

/* ===== INDUSTRY TABS ===== */
.industry-tabs { padding: 80px 0; }
.tab-nav { display: flex; gap: 4px; background: var(--surface); border-radius: 12px; padding: 4px; margin-bottom: 40px; overflow-x: auto; }
.tab-btn { padding: 12px 24px; font-size: 14px; font-weight: 500; color: var(--white-dim); border: none; background: transparent; border-radius: 8px; cursor: pointer; font-family: var(--font-body); white-space: nowrap; transition: all 0.2s; }
.tab-btn.active { background: var(--teal); color: var(--navy); font-weight: 600; }
.tab-btn:hover:not(.active) { color: var(--white); background: rgba(255,255,255,0.05); }
.tab-content { display: none; animation: fadeIn 0.3s ease; }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.tab-panel { background: var(--surface); border: 1px solid rgba(255,255,255,0.06); border-radius: 16px; padding: 48px; }
.tab-panel h3 { font-family: var(--font-display); font-size: 24px; font-weight: 600; margin-bottom: 16px; }
.tab-panel p { color: var(--white-dim); font-size: 15px; line-height: 1.7; margin-bottom: 16px; }
.tab-panel ul { list-style: none; padding: 0; }
.tab-panel ul li { padding: 8px 0; padding-left: 24px; position: relative; color: var(--white-dim); font-size: 14px; }
.tab-panel ul li::before { content: ''; position: absolute; left: 0; top: 16px; width: 8px; height: 8px; background: var(--teal); border-radius: 50%; }

/* ===== PLATFORM DIAGRAM ===== */
.platform-diagram { padding: 80px 0; }
.diagram-wrapper { position: relative; padding: 60px 0; }
.diagram-pillars { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.diagram-pillar { text-align: center; position: relative; }
.diagram-pillar-icon { width: 80px; height: 80px; border-radius: 50%; background: linear-gradient(135deg, var(--teal), var(--teal-dark)); display: flex; align-items: center; justify-content: center; margin: 0 auto 24px; position: relative; }
.diagram-pillar-icon::after { content: ''; position: absolute; inset: -4px; border-radius: 50%; border: 2px solid rgba(0,180,216,0.2); }
.diagram-pillar-icon svg { width: 36px; height: 36px; color: var(--navy); }
.diagram-pillar h3 { font-family: var(--font-display); font-size: 20px; font-weight: 600; margin-bottom: 8px; }
.diagram-pillar p { color: var(--white-dim); font-size: 14px; line-height: 1.6; max-width: 280px; margin: 0 auto; }
.diagram-connections { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 70%; height: 2px; z-index: -1; }
.diagram-connections::before { content: ''; position: absolute; top: -30px; left: 15%; right: 15%; height: 60px; border: 2px dashed rgba(0,180,216,0.2); border-radius: 50%; }
.diagram-center-label { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); background: var(--navy); padding: 8px 20px; border: 1px solid rgba(0,180,216,0.3); border-radius: 100px; font-size: 13px; font-weight: 600; color: var(--teal); white-space: nowrap; z-index: 2; }
@media (max-width: 768px) {
  .diagram-pillars { grid-template-columns: 1fr; gap: 48px; }
  .diagram-connections { display: none; }
  .diagram-center-label { display: none; }
}

/* ===== COMPANY CULTURE ===== */
.culture-section { padding: 80px 0; }
.culture-card { background: linear-gradient(135deg, var(--navy-mid), var(--surface)); border: 1px solid rgba(0,180,216,0.1); border-radius: 20px; padding: 64px; display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.culture-card h2 { font-family: var(--font-display); font-size: 36px; font-weight: 700; margin-bottom: 16px; }
.culture-card h2 span { color: var(--teal); }
.culture-card p { color: var(--white-dim); font-size: 15px; line-height: 1.8; margin-bottom: 32px; }
.culture-visual { display: flex; flex-direction: column; gap: 16px; }
.culture-stat { background: rgba(0,180,216,0.06); border: 1px solid rgba(0,180,216,0.12); border-radius: 12px; padding: 20px 24px; display: flex; align-items: center; gap: 16px; }
.culture-stat-number { font-family: var(--font-display); font-size: 28px; font-weight: 700; color: var(--teal); }
.culture-stat-label { font-size: 14px; color: var(--white-dim); }
@media (max-width: 768px) {
  .culture-card { grid-template-columns: 1fr; padding: 40px 24px; }
}

/* ===== RENEWABLES CTA ===== */
.renewables-cta { padding: 60px 0 80px; }
.renewables-card { background: linear-gradient(135deg, rgba(108,194,74,0.08), rgba(0,180,216,0.06)); border: 1px solid rgba(108,194,74,0.2); border-radius: 16px; padding: 48px; text-align: center; }
.renewables-card h2 { font-family: var(--font-display); font-size: 32px; font-weight: 700; margin-bottom: 16px; }
.renewables-card h2 span { color: var(--green); }
.renewables-card p { color: var(--white-dim); font-size: 15px; line-height: 1.7; max-width: 700px; margin: 0 auto 32px; }
.btn-green { background: var(--green); color: var(--navy); font-weight: 600; padding: 14px 32px; border-radius: 8px; font-size: 15px; transition: all 0.25s; display: inline-flex; align-items: center; gap: 8px; border: none; cursor: pointer; font-family: var(--font-body); }
.btn-green:hover { background: #5db63e; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(108,194,74,0.3); }

/* ===== FOOTER ===== */
.footer { background: var(--navy-mid); border-top: 1px solid rgba(255,255,255,0.06); padding: 64px 0 32px; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 48px; }
.footer-brand h3 { font-family: var(--font-display); font-size: 20px; margin-bottom: 12px; }
.footer-brand h3 span { color: var(--teal); }
.footer-brand p { color: var(--white-dim); font-size: 14px; line-height: 1.6; max-width: 280px; }
.footer-col h4 { font-size: 13px; text-transform: uppercase; letter-spacing: 2px; color: var(--white); font-weight: 600; margin-bottom: 16px; }
.footer-col a { display: block; font-size: 14px; color: var(--white-dim); padding: 4px 0; transition: color 0.2s; }
.footer-col a:hover { color: var(--teal); }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.06); padding-top: 24px; display: flex; justify-content: space-between; align-items: center; font-size: 13px; color: var(--white-dim); }
@media (max-width: 1024px) { .footer-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 640px) { .footer-grid { grid-template-columns: 1fr; } .footer-bottom { flex-direction: column; gap: 12px; text-align: center; } }

/* ===== COOKIE BANNER ===== */
.cookie-banner { position: fixed; bottom: 0; left: 0; right: 0; background: var(--navy-mid); border-top: 1px solid rgba(0,180,216,0.15); padding: 20px; z-index: 10000; transform: translateY(0); transition: transform 0.4s; display: flex; align-items: center; justify-content: center; gap: 24px; }
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-banner p { font-size: 14px; color: var(--white-dim); max-width: 600px; }
.cookie-banner p a { color: var(--teal); text-decoration: underline; }
.cookie-btn { padding: 10px 20px; border-radius: 6px; font-size: 13px; font-weight: 600; cursor: pointer; border: none; font-family: var(--font-body); transition: all 0.2s; }
.cookie-accept { background: var(--teal); color: var(--navy); }
.cookie-accept:hover { background: #33c5e3; }
.cookie-decline { background: transparent; border: 1px solid rgba(255,255,255,0.2); color: var(--white); }
.cookie-decline:hover { border-color: var(--white); }
@media (max-width: 640px) { .cookie-banner { flex-direction: column; text-align: center; gap: 16px; } }

/* ===== ANIMATIONS ===== */
.fade-up { opacity: 0; transform: translateY(24px); transition: opacity 0.6s ease, transform 0.6s ease; }
.fade-up.visible { opacity: 1; transform: translateY(0); }
.stagger-1 { transition-delay: 0.1s; }
.stagger-2 { transition-delay: 0.2s; }
.stagger-3 { transition-delay: 0.3s; }
.stagger-4 { transition-delay: 0.4s; }
.stagger-5 { transition-delay: 0.5s; }
.stagger-6 { transition-delay: 0.6s; }

@media (max-width: 768px) {
  .hero { padding: 120px 0 60px; }
  .hero h1 { font-size: 32px; }
  .hero p { font-size: 16px; }
  .section-title { font-size: 28px; }
  .section { padding: 60px 0; }
}
</style>
</head>
<body>
<!-- Navigation -->
<nav class="nav">
  <div class="nav-inner">
    <a href="index.html" class="nav-logo">Well<span>Stream</span></a>
    <button class="nav-mobile-toggle" onclick="document.querySelector('.nav-links').classList.toggle('active')" aria-label="Toggle menu">
