      <div class="nav-dropdown">
        <button class="nav-dropdown-btn">Platform <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 9l6 6 6-6"/></svg></button>
        <div class="nav-dropdown-menu">
          <a href="platform-overview.html">Platform Overview</a>
