</nav>

<!-- Hero Section -->
<section class="hero">
  <div class="container">
    <div class="hero-badge fade-up">Integrated Energy Platform</div>
    <h1 class="fade-up stagger-1">GET REAL-TIME DATA ACROSS YOUR <span class="accent">ENTIRE OPERATION</span></h1>
    <p class="fade-up stagger-2">The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.</p>
    <div class="hero-ctas fade-up stagger-3">
      <a href="platform-overview.html" class="btn-primary">Explore the Platform <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M12 5l7 7-7 7"/></svg></a>
      <a href="request-demo.html" class="btn-secondary">Request A Demo</a>
