<script>
// Form validation
var form = document.getElementById('demoForm');
var submitBtn = document.getElementById('submitBtn');

function validateEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function showError(fieldName, errorId) {
  var field = form.querySelector('[name="' + fieldName + '"]');
  var error = document.getElementById(errorId);
  field.classList.add('error');
  error.classList.add('show');
}

function clearError(fieldName, errorId) {
  var field = form.querySelector('[name="' + fieldName + '"]');
  var error = document.getElementById(errorId);
  field.classList.remove('error');
  error.classList.remove('show');
}

// Clear errors on input
form.querySelectorAll('input, select, textarea').forEach(function(field) {
  field.addEventListener('input', function() {
    this.classList.remove('error');
    var errorEl = this.parentElement.querySelector('.form-error');
    if (errorEl) errorEl.classList.remove('show');
  });
});

form.addEventListener('submit', function(e) {
  e.preventDefault();
  var valid = true;

  // First name
  if (!form.firstName.value.trim()) { showError('firstName', 'firstNameError'); valid = false; }
  else { clearError('firstName', 'firstNameError'); }

  // Last name
  if (!form.lastName.value.trim()) { showError('lastName', 'lastNameError'); valid = false; }
  else { clearError('lastName', 'lastNameError'); }

  // Email
  if (!form.email.value.trim() || !validateEmail(form.email.value)) { showError('email', 'emailError'); valid = false; }
  else { clearError('email', 'emailError'); }

  // Company
  if (!form.company.value.trim()) { showError('company', 'companyError'); valid = false; }
  else { clearError('company', 'companyError'); }

  // Job title
  if (!form.jobTitle.value.trim()) { showError('jobTitle', 'jobTitleError'); valid = false; }
  else { clearError('jobTitle', 'jobTitleError'); }

  // Country
  if (!form.country.value) { showError('country', 'countryError'); valid = false; }
  else { clearError('country', 'countryError'); }

  if (valid) {
    submitBtn.disabled = true;
    submitBtn.textContent = 'Submitting...';
    setTimeout(function() {
      form.style.display = 'none';
      document.querySelector('.demo-form-card > h2').style.display = 'none';
      document.querySelector('.demo-form-card > p').style.display = 'none';
      document.getElementById('formSuccess').classList.add('show');
    }, 1000);
  }
});

// Scroll animations
var observer = new IntersectionObserver(function(entries) {
  entries.forEach(function(entry) { if (entry.isIntersecting) entry.target.classList.add('visible'); });
}, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });
document.querySelectorAll('.fade-up').forEach(function(el) { observer.observe(el); });
</script>
